import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, texture, mx_worley_noise_float, uniform, time } from 'three/tsl';
import { gsap } from 'gsap';

const createNode = (config, ctx) => {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // Extract colors from config
  const colors = config.intent?.visualSpec?.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // Create the parallax plane with displacement
  const geometry = new THREE.PlaneGeometry(1.8, 1.12, 64, 64);

  // Load textures asynchronously
  const texturePromises = [];

  if (config.imageUrl) {
    texturePromises.push(
      ctx.textureLoader.loadTexture(config.imageUrl).then(tex => {
        tex.colorSpace = THREE.SRGBColorSpace;
        return { type: 'map', texture: tex };
      })
    );
  }

  if (config.depthMapUrl) {
    texturePromises.push(
      ctx.textureLoader.loadTexture(config.depthMapUrl).then(tex => {
        tex.colorSpace = THREE.LinearSRGBColorSpace;
        return { type: 'depth', texture: tex };
      })
    );
  }

  // Build material with TSL nodes
  const materialConfig = {
    color: colors.surface,
    metalness: 0.45,
    roughness: 0.65,
    clearcoat: 0.18
  };

  let displacementMap = null;
  let colorMap = null;

  const createMaterial = () => {
    const positionNode = uniform(new THREE.Vector3(0, 0, 0));
    let displacementNode = null;

    if (displacementMap) {
      displacementNode = texture(displacementMap, uv()).r.mul(0.08);
    } else {
      displacementNode = uniform(0);
    }

    const material = new MeshStandardNodeMaterial({
      color: materialConfig.color,
      metalness: materialConfig.metalness,
      roughness: materialConfig.roughness,
      clearcoat: materialConfig.clearcoat,
      side: THREE.FrontSide,
      toneMapped: true
    });

    if (colorMap) {
      material.colorNode = texture(colorMap);
    }

    material.positionNode = positionNode.add(
      vec3(0, 0, displacementNode)
    );

    return material;
  };

  let material = createMaterial();
  const mesh = new THREE.Mesh(geometry, material);

  // Apply parallax-scroll primitive
  const parallaxPrimitive = ctx.primitives['parallax-scroll'](mesh, {
    intensity: 0.25
  });

  group.add(mesh);

  // Interaction handlers
  const handlers = {};

  handlers.hover = (e) => {
    if (e.type === 'mouseenter') {
      gsap.to(mesh.position, {
        z: 0.15,
        duration: 0.7,
        ease: 'power3.out'
      });
    } else if (e.type === 'mouseleave') {
      gsap.to(mesh.position, {
        z: 0,
        duration: 0.9,
        ease: 'power4.out',
        overwrite: 'auto'
      });
    }
  };

  handlers.click = (e) => {
    gsap.timeline()
      .to(mesh.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out'
      }, 0)
      .to(mesh.scale, {
        x: 1,
        y: 1,
        duration: 0.4,
        ease: 'elastic.out',
        overwrite: 'auto'
      });

    ctx.emit('navigate', { to: 'hub-features.select' });
  };

  // Store handlers in userData
  group.userData.handlers = handlers;

  // Handle texture loading
  Promise.all(texturePromises).then(results => {
    results.forEach(result => {
      if (result.type === 'map') {
        colorMap = result.texture;
        if (material.colorNode && colorMap) {
          material.colorNode = texture(colorMap);
          material.needsUpdate = true;
        }
      } else if (result.type === 'depth') {
        displacementMap = result.texture;
        // Rebuild material with displacement
        geometry.dispose();
        material.dispose();

        material = createMaterial();
        mesh.material = material;
      }
    });
  });

  // Cleanup
  const timelines = [];
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    gsap.killTweensOf(mesh.position);
    gsap.killTweensOf(mesh.scale);

    if (parallaxPrimitive?.cleanup) {
      parallaxPrimitive.cleanup();
    }

    geometry.dispose();
    material.dispose();

    if (colorMap) colorMap.dispose();
    if (displacementMap) displacementMap.dispose();
  };

  return group;
};

export default createNode;
